package com.phoenix.business.repository;import com.phoenix.business.domain.AuditLog;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import org.springframework.data.domain.*;import java.time.Instant;public interface AuditLogRepository extends JpaRepository<AuditLog,Long>{@Query("select a from AuditLog a where (:user is null or lower(a.actorUsername) like lower(concat('%',:user,'%'))) and (:action is null or a.action=:action) and (:entityType is null or a.entityType=:entityType) and (:from is null or a.createdAt>=:from) and (:to is null or a.createdAt<:to) order by a.createdAt desc")Page<AuditLog> filter(@Param("user")String user,@Param("action")String action,@Param("entityType")String entityType,@Param("from")Instant from,@Param("to")Instant to,Pageable p);}
